void Require(bool c,const char* m){if(!c)throw std::runtime_error(m);}
platform::Uuid Instance(unsigned n,bool v7=true){platform::Uuid u{};u.bytes[0]=1;u.bytes[5]=static_cast<platform::byte>(n);u.bytes[6]=v7?0x70:0x40;u.bytes[8]=0x80;u.bytes[15]=static_cast<platform::byte>(n);return u;}
platform::Uuid ExpectedIndexUuid(unsigned n){platform::Uuid u{};const platform::byte prefix[]{0x01,0xa1,0x00,0x8e,0xc1,0x00,0x70};std::copy(std::begin(prefix),std::end(prefix),u.bytes.begin());u.bytes[7]=static_cast<platform::byte>(n);u.bytes[8]=0x80;u.bytes[15]=static_cast<platform::byte>(n);return u;}
std::shared_ptr<const dt::DateValidatedProfileHandleV3> Profile(){
  const platform::Uuid d710{{{0x01,0x9d,0x00,0x00,0x00,0x00,0x70,0x00,0x80,0x00,0x00,0x00,0x00,0x00,0xd7,0x10}}};
  for(const auto& row:dt::CurrentDatatypeTypeCodecIdentityRowsV3())if(dt::IsExactCanonicalDateTypeCodecIdentityV3(row)){
    Require(row.legacy_fields.catalog_snapshot_uuid==d710&&row.legacy_fields.catalog_generation==10&&row.legacy_fields.registry_generation==10,"exact d710 identity authority");
    auto r=dt::BuildCurrentDateValidatedProfileHandleV3(row.legacy_fields.catalog_snapshot_uuid);Require(r.ok(),"date profile");
    Require(r.profile.receipt.catalog_snapshot_uuid==d710&&r.profile.receipt.catalog_generation==10&&r.profile.receipt.registry_generation==10,"exact d710 receipt authority");
    return std::make_shared<const dt::DateValidatedProfileHandleV3>(std::move(r.profile));
  }
  throw std::runtime_error("date identity missing");
}
dt::DateOwnedValueV3 Value(const std::shared_ptr<const dt::DateValidatedProfileHandleV3>& p,std::int32_t d){return {p,dt::DateValueStateV3::value,d};}
std::string_view Detail(const dt::DateDiagnosticFactV3& d){return d.detail;}
bool AlwaysCancel(void*) noexcept{return true;}
struct CancelAt{unsigned calls=0;unsigned at=0;};
bool CancelOnCall(void* context) noexcept{auto& c=*static_cast<CancelAt*>(context);return ++c.calls==c.at;}
struct ScrubProbe{
  std::array<platform::u64,static_cast<std::size_t>(dt::DateScrubClassV3::count)> calls{};
  std::array<platform::u64,static_cast<std::size_t>(dt::DateScrubClassV3::count)> bytes{};
  bool all_zero=true;
};
void ObserveScrub(void* context,dt::DateScrubClassV3 scrub_class,
                  const platform::byte* bytes,platform::u64 extent) noexcept{
  auto& probe=*static_cast<ScrubProbe*>(context);
  const auto index=static_cast<std::size_t>(scrub_class);
  if(index>=probe.calls.size()){probe.all_zero=false;return;}
  ++probe.calls[index];probe.bytes[index]+=extent;
  for(platform::u64 i=0;i<extent;++i)if(bytes[i]!=0){probe.all_zero=false;break;}
}
struct PinProbe{unsigned calls=0;unsigned at=0;std::weak_ptr<const dt::DateValidatedProfileHandleV3> profile;std::weak_ptr<const dt::DateStatisticsProviderEvidenceHandleV3> evidence;long profile_baseline=0;long evidence_baseline=0;long observed_profile=0;long observed_evidence=0;};
bool CancelWithPins(void* context) noexcept{auto& p=*static_cast<PinProbe*>(context);++p.calls;p.observed_profile=p.profile.use_count();p.observed_evidence=p.evidence.use_count();return p.calls==p.at;}

std::vector<platform::byte> Hex(std::string_view s){std::vector<platform::byte> out;out.reserve(s.size()/2);auto nib=[](char c)->unsigned{return c<='9'?static_cast<unsigned>(c-'0'):static_cast<unsigned>(c-'a'+10);};for(std::size_t i=0;i<s.size();i+=2)out.push_back(static_cast<platform::byte>((nib(s[i])<<4)|nib(s[i+1])));return out;}

