  auto renamed_profile=*p;renamed_profile.identity.legacy_fields.canonical_name="fecha";auto renamed_value=dt::DateOwnedValueV3{std::make_shared<const dt::DateValidatedProfileHandleV3>(renamed_profile),dt::DateValueStateV3::value,0};q.value=&renamed_value;auto renamed=dt::ProjectDateIndexValueV3(q);Require(renamed.ok(),"projection accepts translated presentation name");q.value=&v;
