  q.family=dt::DateIndexFamilyV3::bitmap;q.mode=dt::DateProjectionModeV3::equality_hash;auto hash=dt::ProjectDateIndexValueV3(q);Require(hash.ok()&&hash.bytes.size()==32&&hash.resolution.exact_recheck_required,"bitmap hash");
