  q.provider_max_key_bytes=~platform::u64{0};q.family=dt::DateIndexFamilyV3::document_path;q.mode=dt::DateProjectionModeV3::unspecified;auto owner=dt::ProjectDateIndexValueV3(q);Require(!owner.ok()&&owner.owner_fact_only&&owner.diagnostic.diagnostic_code.empty(),"owner fact no optimizer diagnostic");
  q.family=dt::DateIndexFamilyV3::expression;q.selected_conditional_family=nullptr;Require(dt::ProjectDateIndexValueV3(q).owner_fact_only,"conditional unresolved");
  auto selected=dt::ResolveDateIndexFamilyV3(dt::DateIndexFamilyV3::btree);q.selected_conditional_family=&selected;q.mode=dt::DateProjectionModeV3::ascending_nulls_last;Require(dt::ProjectDateIndexValueV3(q).ok(),"conditional exact selection");selected.compatibility_generation=2;Require(dt::ProjectDateIndexValueV3(q).owner_fact_only,"conditional mutation refused");
