  ScrubProbe statistics_decode_probe;statistics_control.scrub_observer_context=&statistics_decode_probe;
  Require(dt::DecodeDateStatisticsProjectionV3(p,statistics_bytes.bytes,statistics_control).ok(),"statistics observed decode");
  require_record_scrubs(statistics_decode_probe,3,27,dt::DateScrubClassV3::statistics_decode_reencode,4608,2,0,"statistics decode exact zeroed scrubs");
  ScrubProbe statistics_cancel_probe;CancelAt statistics_cancel{0,3};statistics_control.cancelled=&CancelOnCall;statistics_control.cancellation_context=&statistics_cancel;statistics_control.scrub_observer_context=&statistics_cancel_probe;const auto statistics_cancelled=dt::EncodeDateStatisticsProjectionV3(statistics,statistics_control);Require(!statistics_cancelled.ok()&&statistics_cancelled.bytes.empty()&&statistics_cancelled.diagnostic.diagnostic_code=="PROCESS.CANCELLED","statistics final cancellation");require_record_scrubs(statistics_cancel_probe,3,27,dt::DateScrubClassV3::statistics_decode_reencode,4608,2,512,"statistics cancel exact zeroed scrubs");

  ScrubProbe backup_encode_probe;dt::DateExecutionControlV3 backup_control;backup_control.observe_scrubbed=&ObserveScrub;backup_control.scrub_observer_context=&backup_encode_probe;
  const auto backup_bytes=dt::EncodeDateBackupTupleV3(value,backup_control);Require(backup_bytes.ok(),"backup stack hash encode");
  require_record_scrubs(backup_encode_probe,3,18,dt::DateScrubClassV3::backup_decode_reencode,300,0,0,"backup encode exact zeroed scrubs");
  ScrubProbe backup_decode_probe;backup_control.scrub_observer_context=&backup_decode_probe;
  Require(dt::DecodeDateBackupTupleNoAllocV3(*p,false,backup_bytes.bytes,backup_control).ok(),"backup observed decode");
  require_record_scrubs(backup_decode_probe,2,12,dt::DateScrubClassV3::backup_decode_reencode,300,0,0,"backup decode exact zeroed scrubs");
  ScrubProbe backup_cancel_probe;CancelAt backup_cancel{0,2};backup_control.cancelled=&CancelOnCall;backup_control.cancellation_context=&backup_cancel;backup_control.scrub_observer_context=&backup_cancel_probe;
  const auto backup_cancelled=dt::EncodeDateBackupTupleV3(value,backup_control);Require(!backup_cancelled.ok()&&backup_cancelled.bytes.empty()&&backup_cancelled.diagnostic.diagnostic_code=="PROCESS.CANCELLED","backup final cancellation");
  require_record_scrubs(backup_cancel_probe,3,18,dt::DateScrubClassV3::backup_decode_reencode,300,0,300,"backup cancel exact zeroed scrubs");
